12	let client: Stripe | null = null;
13	
14	export function stripe(): Stripe {
15	  if (!process.env.STRIPE_SECRET_KEY) throw new Error("Stripe is not configured");
16	  if (!client) client = new Stripe(process.env.STRIPE_SECRET_KEY);
