20	/** Stripe's hard limit on a single metadata VALUE. */
21	export const STRIPE_METADATA_VALUE_MAX = 500;
22	
23	/**
24	 * Serialise a payload for Stripe metadata, refusing rather than truncating.
25	 *
26	 * WHY THIS EXISTS. Every one of these payloads used to be written as
27	 * `JSON.stringify(x).slice(0, 490)`. A slice through JSON produces a string that
28	 * is no longer JSON, and the consumer's `JSON.parse` throws inside a `try` that
29	 * returns `null` on failure — at which point `fulfilCheckoutSession` cannot see an
30	 * order, a resize or a disk expansion in the session, and falls through to its
31	 * plain wallet-top-up branch. The customer's card is charged, the money lands in
32	 * their wallet, **no server is created, no error is shown and no failure row is
33	 * written**. Silent, and invisible from every surface we own.
34	 *
35	 * The correct behaviour was already argued for elsewhere in this file, about the
36	 * card leg: "Refuse to open a session rather than take the money and discover it
37	 * at confirm time — nothing has been charged at this point." That reasoning
38	 * applies identically here, so it is applied identically. Throwing happens BEFORE
39	 * `checkout.sessions.create`, so the customer sees a failure on a page where they
40	 * have paid nothing, which is the cheapest possible moment to fail.
41	 *
42	 * Never re-introduce a slice here. If a payload legitimately outgrows the cap, the
43	 * fix is to persist it and put a key in metadata — never to send half of it.
44	 */
45	export function packMetadata(label: string, payload: unknown): string {
46	  const json = JSON.stringify(payload);
47	  if (json.length > STRIPE_METADATA_VALUE_MAX) {
48	    throw new Error(
49	      `${label} is ${json.length} characters, over Stripe's ${STRIPE_METADATA_VALUE_MAX}-character metadata limit. ` +
50	        `Refusing to create a payment session rather than send a truncated payload that would take the money and ` +
51	        `provision nothing.`,
52	    );
53	  }
54	  return json;
55	}
