57	/**
58	 * Create a Checkout session that pays for a VPS order directly (no wallet pre-fund).
59	 *
60	 * `amountCents` is the CARD leg only (the remainder after wallet credit); the FULL
61	 * order total rides along in metadata as `nxeonOrderPrice` so the confirm route can
62	 * settle the price this order was SOLD at instead of re-pricing it once the card
63	 * has already cleared. That re-pricing — and the silent wallet draw that paid for
64	 * it — is the H2 incident described on `OrderPrice` in lib/order.ts.
65	 *
66	 * `sold` lets the caller hand in the very quote it split the payment from, so the
67	 * card leg and the stamped total are two halves of ONE pricing. When it is omitted
68	 * the order is priced here, once, at the moment the session is created — still
69	 * before any money moves, which is the property that matters.
70	 */
71	export async function createOrderCheckout(
72	  user: { id: string; email: string },
73	  amountCents: number,
74	  intent: OrderIntent,
75	  sold?: OrderPrice | null,
76	): Promise<string | null> {
77	  if (!stripeConfigured() || amountCents <= 0) return null;
78	  const base = process.env.APP_URL ?? "http://localhost:3000";
79	  const price = sold ?? orderPriceOf(await orderQuote(intent));
80	  // The card leg is a PART of the total; a card charge larger than the whole order
81	  // means the two were priced against different worlds and the wallet would have to
82	  // absorb a negative. Refuse to open a session rather than take the money and
83	  // discover it at confirm time — nothing has been charged at this point.
84	  if (price.chargeCents < amountCents) {
85	    throw new Error(
86	      `Order checkout: card leg ${amountCents}c exceeds the order total ${price.chargeCents}c`,
87	    );
88	  }
89	  // SSH keys are long; keep them out of Stripe metadata (500-char cap) — addable after deploy.
90	  const slim: OrderIntent = { ...intent, sshPublicKey: undefined, sshKeyName: undefined };
91	  const session = await stripe().checkout.sessions.create({
92	    mode: "payment",
93	    customer_email: user.email,
94	    line_items: [
95	      {
96	        price_data: {
97	          currency: "usd",
98	          product_data: { name: `Nxeon VPS — ${intent.hostname}` },
99	          unit_amount: amountCents,
100	        },
101	        quantity: 1,
102	      },
103	    ],
104	    metadata: {
105	      nxeonUserId: user.id,
106	      nxeonOrder: packMetadata("Order intent", slim),
107	      // Its OWN key, not a field inside `nxeonOrder`, so the two are independently
108	      // sized and a long intent can never displace the price.
109	      nxeonOrderPrice: packMetadata("Order price", price),
110	    },
111	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
112	    cancel_url: `${base}/dashboard/deploy?canceled=1`,
113	  });
114	  return session.url;
115	}
