296	/**
297	 * Credit a user's wallet for a completed Checkout session, idempotently.
298	 * Called from both the success-redirect confirm route (works without HTTPS)
299	 * and the webhook (belt-and-suspenders once HTTPS is available).
300	 * Returns true if a credit was applied this call.
301	 */
302	export async function creditCheckoutSession(sessionId: string): Promise<boolean> {
303	  const session = await stripe().checkout.sessions.retrieve(sessionId);
304	  const userId = session.metadata?.nxeonUserId;
305	  const cents = session.amount_total ?? 0;
306	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
307	
308	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
309	  // session id inside the description.
310	  const legacy = await db.walletTransaction.findFirst({
311	    where: { stripeSessionId: null, description: { contains: session.id } },
312	  });
313	  if (legacy) return false;
314	
315	  // Is this credit a product the customer bought, or the funding leg of something
316	  // else they bought? Only the first is a "Wallet top-up" and only the first gets
317	  // a billing document — see isPurchaseLegSession for the incident.
318	  const purchaseLeg = isPurchaseLegSession(session.metadata);
319	
320	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
321	  // read-then-write check. The confirm-redirect and the webhook can arrive
322	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
323	  // only the database can safely decide the winner. P2002 == already credited.
324	  const ops: Prisma.PrismaPromise<unknown>[] = [
325	    db.walletTransaction.create({
326	      data: {
327	        userId,
328	        amountCents: cents,
329	        description: `Stripe payment (${session.id})`,
330	        stripeSessionId: session.id,
331	      },
332	    }),
333	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
334	    db.notification.create({
335	      data: {
336	        userId,
337	        title: `Payment of $${(cents / 100).toFixed(2)} received`,
338	        href: "/dashboard/billing",
339	      },
340	    }),
341	  ];
342	  // Index of the invoice-create inside `ops`, or -1 when no invoice is issued
343	  // (a purchase leg). Used to recover the new invoice's id for the receipt email.
344	  let invoiceOpIndex = -1;
345	  if (!purchaseLeg) {
346	    // PAID invoice for the top-up. Created in the SAME guarded transaction as
347	    // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
348	    // the credit idempotent also prevents a duplicate invoice on replay.
349	    //
350	    // A purchase leg is deliberately left undocumented HERE: the order, resize or
351	    // disk-expansion it funds issues the one invoice for the whole purchase, and
352	    // that document — not this one — is what the customer's card statement shows.
353	    // If the fulfilment then fails the money stays in the wallet as an ordinary
354	    // credit (ledger row + notification), and the invoice is issued by whatever it
355	    // is eventually spent on; inventing a top-up document at that point would
356	    // double-count the same dollars all over again the moment they deploy.
357	    // Remember WHERE in the batch this lands, so the created row's id can be read
358	    // back out of the transaction result. The receipt email promises the customer
359	    // an attached invoice, and it can only keep that promise if it knows the id.
360	    invoiceOpIndex = ops.length;
361	    ops.push(
362	      db.invoice.create({
363	        data: invoiceCreateData({
364	          userId,
365	          description: "Wallet top-up",
366	          status: "PAID",
367	          lineItems: [
368	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
369	          ],
370	        }),
371	      }),
372	    );
373	  }
374	  let invoiceId: string | undefined;
375	  try {
376	    const results = await db.$transaction(ops);
377	    if (invoiceOpIndex >= 0) {
378	      const created = results[invoiceOpIndex] as { id?: string } | undefined;
379	      invoiceId = created?.id;
380	    }
381	  } catch (e) {
382	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
383	    throw e;
384	  }
385	  // A funded wallet is the referred user's first paid action — reward both sides.
386	  try {
387	    const { maybeRewardReferral } = await import("./actions-growth");
388	    await maybeRewardReferral(userId);
389	  } catch { /* best-effort */ }
390	  try {
391	    const u = await db.user.findUnique({ where: { id: userId } });
392	    if (u) {
393	      const { sendMail, emails } = await import("./mailer");
394	      // Say what the money was for. On a purchase leg it is emphatically NOT a
395	      // top-up, and a receipt that calls it one is the same false statement the
396	      // duplicate invoice used to make, just in the customer's inbox.
397	      // The third argument is the promise, and it is the truth: we claim an attached
398	      // invoice only when there is an invoice id to attach. A purchase leg issues no
399	      // top-up invoice (the order does), so its receipt points at billing history
400	      // instead of promising a file that was never generated.
401	      const tpl = emails.receipt(
402	        `$${(cents / 100).toFixed(2)}`,
403	        purchaseLeg ? "your Nxeon order" : "wallet top-up",
404	        !!invoiceId,
405	      );
406	      // `kind` + `userId` hands this to the preference policy in lib/prefs.ts.
407	      // A receipt is ACCOUNT tier — suppressible by email if the customer turned
408	      // account email off. This is the one send site where that toggle actually
409	      // bites today, so it is the one that made the switch a lie.
410	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html, userId, kind: "receipt", invoiceId });
411	    }
412	  } catch { /* best-effort */ }
413	  return true;
414	}
