116	export type CardUser = {
117	  id: string;
118	  email: string;
119	  name?: string | null;
120	  stripeCustomerId: string | null;
121	  stripePaymentMethodId: string | null;
122	};
123	
124	/** True when this account can actually be charged off-session right now. */
125	export function hasChargeableCard(user: {
126	  stripeCustomerId: string | null;
127	  stripePaymentMethodId: string | null;
128	}): boolean {
129	  return stripeConfigured() && !!user.stripeCustomerId && !!user.stripePaymentMethodId;
130	}
