132	/**
133	 * Get-or-create the Stripe customer for an account and remember its id.
134	 *
135	 * `User.stripeCustomerId` has no UNIQUE constraint (the schema is frozen), so two
136	 * concurrent "Add card" clicks could otherwise mint two Stripe customers for one
137	 * person and strand the card on whichever one lost. The idempotency key — derived
138	 * only from our own user id — is what stops that: Stripe replays the first
139	 * customer instead of creating a second.
140	 */
141	export async function ensureStripeCustomer(user: CardUser): Promise<string> {
142	  if (user.stripeCustomerId) return user.stripeCustomerId;
143	  const fresh = await db.user.findUnique({
144	    where: { id: user.id },
145	    select: { stripeCustomerId: true },
146	  });
147	  if (fresh?.stripeCustomerId) return fresh.stripeCustomerId;
148	
149	  const customer = await stripe().customers.create(
150	    {
151	      email: user.email,
152	      name: user.name || undefined,
153	      metadata: { nxeonUserId: user.id },
154	    },
155	    { idempotencyKey: `nxeon_customer_${user.id}` },
156	  );
157	  await db.user.update({ where: { id: user.id }, data: { stripeCustomerId: customer.id } });
158	  return customer.id;
159	}
