161	/**
162	 * Hosted Checkout session in `mode: "setup"` — how a customer saves a card.
163	 *
164	 * Checkout rather than Stripe Elements because there is no Elements/Stripe.js
165	 * integration anywhere in this codebase and no publishable key plumbed to the
166	 * browser; a redirect to Stripe's own page reuses the exact flow that already
167	 * takes money for deploys, upgrades and top-ups.
168	 *
169	 * `usage: "off_session"` is load-bearing: it records a mandate that covers the
170	 * unattended renewal charges we make later. Without it many issuers (and every
171	 * SCA-regulated card) reject the first off-session charge outright, which would
172	 * turn "saved card" into "card that is declined once a month".
173	 */
174	export async function createCardSetupSession(
175	  user: CardUser,
176	  returnPath = "/dashboard/billing",
177	): Promise<string | null> {
178	  if (!stripeConfigured()) return null;
179	  const customerId = await ensureStripeCustomer(user);
180	  const base = appBase();
181	  const session = await stripe().checkout.sessions.create({
182	    mode: "setup",
183	    customer: customerId,
184	    payment_method_types: ["card"],
185	    setup_intent_data: { metadata: { nxeonUserId: user.id } },
186	    metadata: { nxeonUserId: user.id, nxeonCardSetup: "1" },
187	    // Deliberately NOT /api/stripe/confirm. A setup session has no amount and
188	    // `payment_status: "unpaid"`, so the shared fulfil path would classify it as a
189	    // wallet top-up and flash "Payment received — your balance updates within
190	    // seconds" at someone who only saved a card. We finalise through our own
191	    // server action instead.
192	    success_url: `${base}${returnPath}?card_setup={CHECKOUT_SESSION_ID}`,
193	    cancel_url: `${base}${returnPath}?card_setup=canceled`,
194	  });
195	  return session.url;
196	}
