198	/** Mirror the display fields + payment method for a card onto the account. */
199	async function persistCard(userId: string, customerId: string, pm: Stripe.PaymentMethod) {
200	  await db.user.update({
201	    where: { id: userId },
202	    data: {
203	      stripeCustomerId: customerId,
204	      stripePaymentMethodId: pm.id,
205	      cardBrand: pm.card?.brand ?? null,
206	      cardLast4: pm.card?.last4 ?? null,
207	      cardExpMonth: pm.card?.exp_month ?? null,
208	      cardExpYear: pm.card?.exp_year ?? null,
209	      // A brand-new card gets a fresh expiry-warning budget, otherwise a customer
210	      // who replaces an expiring card would never be warned about the new one.
211	      cardExpiryNotifiedAt: null,
212	    },
213	  });
214	}
215	
216	export type SavedCard = { brand: string | null; last4: string | null; expMonth: number | null; expYear: number | null };
217	
218	/**
219	 * Finalise a completed setup Checkout session: read the payment method off it,
220	 * make it the customer's default and mirror it onto the account.
221	 *
222	 * Verifies `metadata.nxeonUserId` against the caller. The session id travels in a
223	 * URL the customer can edit, so without that check a customer could paste someone
224	 * else's session id and attach their card to their own account.
225	 */
226	export async function saveCardFromSetupSession(
227	  sessionId: string,
228	  userId: string,
229	): Promise<{ card?: SavedCard; error?: string }> {
230	  if (!stripeConfigured()) return { error: "Card payments are not configured." };
231	  let session: Stripe.Checkout.Session;
232	  try {
233	    session = await stripe().checkout.sessions.retrieve(sessionId, { expand: ["setup_intent"] });
234	  } catch {
235	    return { error: "We couldn't read that card setup. Try adding the card again." };
236	  }
237	  if (session.mode !== "setup" || session.metadata?.nxeonUserId !== userId) {
238	    return { error: "That card setup doesn't belong to this account." };
239	  }
240	  if (session.status !== "complete") {
241	    return { error: "The card wasn't saved — the setup wasn't completed." };
242	  }
243	  const setupIntent = session.setup_intent as Stripe.SetupIntent | string | null;
244	  const pmRef =
245	    typeof setupIntent === "string" ? null : (setupIntent?.payment_method ?? null);
246	  const pmId = typeof pmRef === "string" ? pmRef : (pmRef?.id ?? null);
247	  const customerId =
248	    typeof session.customer === "string" ? session.customer : (session.customer?.id ?? null);
249	  if (!pmId || !customerId) return { error: "The card wasn't saved — no payment method came back." };
250	
251	  const pm = await stripe().paymentMethods.retrieve(pmId);
252	  // Checkout already attached the method to the customer; making it the default
253	  // means the adoption backstop below and anything Stripe-side pick the same card.
254	  await stripe()
255	    .customers.update(customerId, { invoice_settings: { default_payment_method: pmId } })
256	    .catch(() => {
257	      /* non-fatal: our own stripePaymentMethodId is the source of truth for charging */
258	    });
259	  await persistCard(userId, customerId, pm);
260	  return {
261	    card: {
262	      brand: pm.card?.brand ?? null,
263	      last4: pm.card?.last4 ?? null,
264	      expMonth: pm.card?.exp_month ?? null,
265	      expYear: pm.card?.exp_year ?? null,
266	    },
267	  };
268	}
