270	/**
271	 * Backstop for the closed-tab case.
272	 *
273	 * Checkout attaches the card to the Stripe customer BEFORE our `success_url` ever
274	 * runs. A customer who completes the Stripe page and then closes the tab has a
275	 * perfectly good card on file at Stripe and none on file here — and would be
276	 * dunned and suspended for it. This is the same class of bug as the Stripe
277	 * fulfilment incident: a browser redirect must never be the only trigger.
278	 *
279	 * Adoption is deliberately narrow. It requires a `card.setup_started` audit row
280	 * newer than any `card.removed` row and no older than a week, so a card the
281	 * customer explicitly REMOVED can never be silently resurrected and charged.
282	 */
283	export async function adoptUnclaimedCards(now = new Date()): Promise<number> {
284	  if (!stripeConfigured()) return 0;
285	  const since = new Date(now.getTime() - SETUP_INTENT_TTL_DAYS * 86400_000);
286	  const starts = await db.auditLog.findMany({
287	    where: { action: CARD_SETUP_STARTED, createdAt: { gt: since } },
288	    orderBy: { createdAt: "desc" },
289	    take: 200,
290	  });
291	  const userIds = [...new Set(starts.map((a) => a.userId).filter((v): v is string => !!v))];
292	  if (userIds.length === 0) return 0;
293	
294	  let adopted = 0;
295	  for (const userId of userIds) {
296	    const user = await db.user.findUnique({ where: { id: userId } });
297	    if (!user?.stripeCustomerId || user.stripePaymentMethodId) continue;
298	
299	    const startedAt = starts.find((a) => a.userId === userId)!.createdAt;
300	    const removed = await db.auditLog.findFirst({
301	      where: { userId, action: CARD_REMOVED },
302	      orderBy: { createdAt: "desc" },
303	    });
304	    if (removed && removed.createdAt > startedAt) continue; // removal is the later intent
305	
306	    try {
307	      const list = await stripe().paymentMethods.list({
308	        customer: user.stripeCustomerId,
309	        type: "card",
310	        limit: 5,
311	      });
312	      const pm = list.data[0]; // newest first
313	      if (!pm) continue;
314	      await persistCard(userId, user.stripeCustomerId, pm);
315	      await db.auditLog.create({
316	        data: {
317	          userId,
318	          action: "card.adopted",
319	          detail: `${cardDisplayLabel({
320	            brand: pm.card?.brand ?? null,
321	            last4: pm.card?.last4 ?? null,
322	            expMonth: pm.card?.exp_month ?? null,
323	            expYear: pm.card?.exp_year ?? null,
324	          })} (saved at Stripe but never confirmed in the browser)`,
325	        },
326	      });
327	      adopted++;
328	    } catch (e) {
329	      console.error(`[cards] could not adopt card for ${userId}`, e);
330	    }
331	  }
332	  return adopted;
333	}
