335	/**
336	 * Remove the saved card: detach at Stripe FIRST, and only clear our columns once
337	 * Stripe agrees the method is gone. Clearing locally while the method is still
338	 * attached would let `adoptUnclaimedCards` re-adopt it and charge a card the
339	 * customer had removed. A method that is already missing counts as removed.
340	 */
341	export async function detachSavedCard(userId: string): Promise<{ ok?: true; error?: string }> {
342	  const user = await db.user.findUnique({ where: { id: userId } });
343	  if (!user) return { error: "Account not found." };
344	  if (!user.stripePaymentMethodId) {
345	    await clearCardColumns(userId);
346	    return { ok: true };
347	  }
348	  if (stripeConfigured()) {
349	    try {
350	      await stripe().paymentMethods.detach(user.stripePaymentMethodId);
351	    } catch (e) {
352	      const err = asStripeError(e);
353	      if (err?.code !== "resource_missing") {
354	        console.error("[cards] detach failed", e);
355	        return { error: "We couldn't remove the card just now. Please try again in a moment." };
356	      }
357	    }
358	  }
359	  await clearCardColumns(userId);
360	  return { ok: true };
361	}
362	
363	async function clearCardColumns(userId: string) {
364	  await db.user.update({
365	    where: { id: userId },
366	    data: {
367	      stripePaymentMethodId: null,
368	      cardBrand: null,
369	      cardLast4: null,
370	      cardExpMonth: null,
371	      cardExpYear: null,
372	      cardExpiryNotifiedAt: null,
373	    },
374	  });
375	}
