377	/**
378	 * A customer who saves a card mid-dunning has been told (by
379	 * `emails.paymentFailed`) that we'll "charge it straight away". Bringing the
380	 * scheduled retry forward is what makes that copy true — the next sweep picks it
381	 * up instead of waiting for the day-3 or day-5 slot. The failure COUNT is left
382	 * alone: the money is still owed.
383	 */
384	export async function retryDunningNow(userId: string): Promise<number> {
385	  const res = await db.server.updateMany({
386	    where: { userId, dunningStage: { gt: 0 } },
387	    data: { dunningNextAt: new Date() },
388	  });
389	  return res.count;
