392	/* ------------------------------------------------------------------ *
393	 * Off-session charging
394	 * ------------------------------------------------------------------ */
395	
396	type StripeErrorLike = {
397	  type?: string;
398	  rawType?: string;
399	  code?: string;
400	  decline_code?: string;
401	  message?: string;
402	  payment_intent?: { id?: string; status?: string };
403	};
404	
405	function asStripeError(e: unknown): StripeErrorLike | null {
406	  if (!e || typeof e !== "object") return null;
407	  const err = e as StripeErrorLike;
408	  return err.rawType || err.type?.startsWith("Stripe") ? err : null;
409	}
410	
411	export type OffSessionResult =
412	  /** Money captured. `amountCents` is what Stripe actually took, not what we asked for. */
413	  | { ok: true; paymentIntentId: string; amountCents: number; replayed: boolean }
414	  /** 3-D Secure or equivalent: the customer must approve it with their bank. */
415	  | { ok: false; kind: "requires_action"; paymentIntentId: string | null; message: string }
416	  /** The issuer said no. A real dunning event. */
417	  | { ok: false; kind: "declined"; message: string; code?: string }
418	  /** Our side or Stripe's side wobbled. NOT the customer's fault — never dun for it. */
419	  | { ok: false; kind: "transient"; message: string }
420	  /** Nothing to charge with (no card, Stripe off, amount under Stripe's floor). */
421	  | { ok: false; kind: "unavailable"; message: string };
422	
423	/**
424	 * Stable per-purpose marker written into PaymentIntent metadata.
425	 *
426	 * This is a SECOND idempotency guard that does not expire. Stripe's own
427	 * idempotency keys are only honoured for 24 hours, and our dunning schedule spans
428	 * six days, so the key alone cannot answer "have we already been paid for this
429	 * period?". Before charging we look for a live PaymentIntent carrying this marker
430	 * and reuse it — so a crash between "Stripe captured the money" and "we recorded
431	 * the payment intent id" can never turn into a second charge.
432	 */
433	export function renewalChargeMarker(serverId: string, periodStart: Date): string {
434	  return `renew:${serverId}:${periodStart.toISOString()}`;
435	}
436	
437	/** Marker for an automatic wallet top-up: at most one per account per day. */
438	export function autoRechargeMarker(userId: string, now: Date): string {
439	  return `autorecharge:${userId}:${now.toISOString().slice(0, 10)}`;
440	}
441	
442	/** Look for a charge we may already have made for this exact purpose. */
443	async function findChargeByMarker(
444	  customerId: string,
445	  marker: string,
446	): Promise<Stripe.PaymentIntent | null> {
447	  // 25 is generous: renewals are monthly and this is scoped to one customer, so a
448	  // charge made minutes or days ago is always inside this window.
449	  const list = await stripe().paymentIntents.list({ customer: customerId, limit: 25 });
450	  const mine = list.data.filter((pi) => pi.metadata?.nxeonChargeKey === marker);
451	  return (
452	    mine.find((pi) => pi.status === "succeeded") ??
453	    mine.find((pi) => pi.status === "requires_action") ??
454	    mine.find((pi) => pi.status === "processing") ??
455	    null
456	  );
457	}
458	
459	/**
460	 * Charge the saved card off-session (no customer present).
461	 *
462	 * Two independent idempotency guards, because this moves real money on a timer
463	 * that retries:
464	 *  1. `marker` — pre-flight lookup of a live PaymentIntent for this exact purpose.
465	 *     Survives forever, catches the crash-after-capture window.
466	 *  2. `idempotencyKey` — Stripe replays the identical request instead of charging
467	 *     twice when two sweeps overlap. Only good for 24h, hence guard 1.
468	 */
469	export async function chargeSavedCardOffSession(opts: {
470	  user: CardUser;
471	  amountCents: number;
472	  description: string;
473	  marker: string;
474	  idempotencyKey: string;
475	  metadata?: Record<string, string>;
476	}): Promise<OffSessionResult> {
477	  const { user, amountCents, description, marker, idempotencyKey } = opts;
478	  if (!stripeConfigured()) return { ok: false, kind: "unavailable", message: "Stripe is not configured" };
479	  if (!user.stripeCustomerId || !user.stripePaymentMethodId) {
480	    return { ok: false, kind: "unavailable", message: "No saved card" };
481	  }
482	  // `walletSplit` already keeps the card leg at or above Stripe's floor; this is
483	  // the belt-and-braces check so a future caller can't send a rejectable amount.
484	  if (amountCents < STRIPE_MIN_CENTS) {
485	    return { ok: false, kind: "unavailable", message: `Below Stripe minimum (${STRIPE_MIN_CENTS}c)` };
486	  }
487	
488	  // Guard 1: did we already charge for this purpose?
489	  try {
490	    const existing = await findChargeByMarker(user.stripeCustomerId, marker);
491	    if (existing?.status === "succeeded") {
492	      return {
493	        ok: true,
494	        paymentIntentId: existing.id,
495	        amountCents: existing.amount_received || existing.amount,
496	        replayed: true,
497	      };
498	    }
499	    if (existing?.status === "requires_action") {
500	      // A 3-D Secure wall does not move: retrying the SAME card off-session hits it
501	      // again, so reuse the existing intent (and its link) rather than piling up a
502	      // new challenge every retry. A DIFFERENT card is a different story — if the
503	      // customer has since saved one, cancel the stale challenge and really try it,
504	      // otherwise saving a new card would silently change nothing.
505	      const pendingPm =
506	        typeof existing.payment_method === "string"
507	          ? existing.payment_method
508	          : (existing.payment_method?.id ?? null);
509	      if (pendingPm === user.stripePaymentMethodId) {
510	        return {
511	          ok: false,
512	          kind: "requires_action",
513	          paymentIntentId: existing.id,
514	          message: "Awaiting bank confirmation",
515	        };
516	      }
517	      await cancelIfUnconfirmed(existing.id);
518	    }
519	    if (existing?.status === "processing") {
520	      return { ok: false, kind: "transient", message: "A charge for this period is still settling" };
521	    }
522	  } catch (e) {
523	    // A failed lookup must not become a blind second charge.
524	    console.error("[cards] pre-flight charge lookup failed", e);
525	    return { ok: false, kind: "transient", message: "Could not verify existing charges" };
526	  }
527	
528	  try {
529	    const pi = await stripe().paymentIntents.create(
530	      {
531	        amount: amountCents,
532	        currency: "usd",
533	        customer: user.stripeCustomerId,
534	        payment_method: user.stripePaymentMethodId,
535	        confirm: true,
536	        off_session: true,
537	        // No browser exists here, so a redirect-based next_action could never be
538	        // satisfied — and asking for one is what makes Stripe demand a return_url.
539	        automatic_payment_methods: { enabled: true, allow_redirects: "never" },
540	        description,
541	        metadata: { ...(opts.metadata ?? {}), nxeonUserId: user.id, nxeonChargeKey: marker },
542	      },
543	      { idempotencyKey },
544	    );
545	    if (pi.status === "succeeded") {
546	      return { ok: true, paymentIntentId: pi.id, amountCents: pi.amount_received || pi.amount, replayed: false };
547	    }
548	    if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
549	      return { ok: false, kind: "requires_action", paymentIntentId: pi.id, message: "Bank confirmation required" };
550	    }
551	    if (pi.status === "processing") {
552	      return { ok: false, kind: "transient", message: "Payment is still processing" };
553	    }
554	    return { ok: false, kind: "declined", message: `Payment could not be completed (${pi.status})` };
555	  } catch (e) {
556	    return classifyChargeError(e);
557	  }
558	}
