560	/**
561	 * Split a charge failure into the three cases that deserve different treatment:
562	 * the bank wants the customer to confirm, the bank said no, or nothing about the
563	 * customer went wrong at all.
564	 *
565	 * The default is `transient` on purpose. A misclassified transient error costs us
566	 * a delayed renewal; a misclassified decline costs a paid-up customer their
567	 * server. Unknown always resolves to the direction that cannot suspend anyone.
568	 */
569	function classifyChargeError(e: unknown): OffSessionResult {
570	  const err = asStripeError(e);
571	  const message = String(err?.message ?? (e as Error)?.message ?? e).slice(0, 300);
572	  if (!err) return { ok: false, kind: "transient", message };
573	
574	  // 3-D Secure surfaces as a card error with this code, with the PI attached.
575	  if (err.code === "authentication_required" || err.payment_intent?.status === "requires_action") {
576	    return {
577	      ok: false,
578	      kind: "requires_action",
579	      paymentIntentId: err.payment_intent?.id ?? null,
580	      message,
581	    };
582	  }
583	  if (err.rawType === "card_error") {
584	    return { ok: false, kind: "declined", message, code: err.decline_code ?? err.code };
585	  }
586	  // The saved method vanished at Stripe (detached elsewhere, customer deleted).
587	  // Not a decline — there is nothing to retry until a new card is saved.
588	  if (err.rawType === "invalid_request_error" && err.code === "resource_missing") {
589	    return { ok: false, kind: "unavailable", message };
590	  }
591	  return { ok: false, kind: "transient", message };
592	}
