606	/**
607	 * Credit the wallet for money a card just paid, exactly once.
608	 *
609	 * Idempotency is the UNIQUE index on `WalletTransaction.stripePaymentIntentId`,
610	 * NOT a read-then-write check: a retried sweep and a replayed Stripe request can
611	 * both arrive with the same intent id, and only the database can safely pick the
612	 * winner. P2002 means someone already credited it — that is a success, not an error.
613	 *
614	 * No invoice for a renewal leg: the renewal transaction issues one PAID invoice
615	 * for the whole renewal, and a second document for the card portion would
616	 * double-count the same revenue. Callers that ARE the whole payment (a wallet
617	 * auto-top-up) pass `invoiceDescription` and get one in the same guarded write.
618	 */
619	export async function creditOffSessionCharge(opts: {
620	  userId: string;
621	  amountCents: number;
622	  description: string;
623	  paymentIntentId: string;
624	  invoiceDescription?: string;
625	}): Promise<boolean> {
626	  if (opts.amountCents <= 0) return false;
627	  try {
628	    await db.$transaction([
629	      db.walletTransaction.create({
630	        data: {
631	          userId: opts.userId,
632	          amountCents: opts.amountCents,
633	          description: opts.description,
634	          stripePaymentIntentId: opts.paymentIntentId,
635	        },
636	      }),
637	      db.user.update({
638	        where: { id: opts.userId },
639	        data: { balanceCents: { increment: opts.amountCents } },
640	      }),
641	      ...(opts.invoiceDescription
642	        ? [
643	            db.invoice.create({
644	              data: invoiceCreateData({
645	                userId: opts.userId,
646	                description: opts.invoiceDescription,
647	                status: "PAID",
648	                lineItems: [
649	                  {
650	                    description: opts.invoiceDescription,
651	                    qty: 1,
652	                    unitCents: opts.amountCents,
653	                    amountCents: opts.amountCents,
654	                  },
655	                ],
656	              }),
657	            }),
658	          ]
659	        : []),
660	    ]);
661	    return true;
662	  } catch (e) {
663	    if ((e as { code?: string })?.code === "P2002") return false; // already credited
664	    throw e;
665	  }
