668	/**
669	 * Hosted Checkout link for an outstanding renewal balance.
670	 *
671	 * Carries ONLY `nxeonUserId` in metadata, which makes the shared, already-proven
672	 * fulfilment path treat it as a wallet top-up: the money lands as wallet credit
673	 * and the next sweep renews from the wallet. That is why this is also the answer
674	 * to 3-D Secure — Checkout collects the bank challenge on Stripe's own page, so we
675	 * never need Stripe.js in the browser or a second confirmation code path.
676	 *
677	 * The quoted amount is the remainder the wallet cannot cover AT THIS MOMENT. If
678	 * the customer spends their credit before paying, the next sweep simply recomputes
679	 * the split and asks the card for the new remainder — it self-heals rather than
680	 * over- or under-charging.
681	 */
682	export async function createOutstandingCheckout(opts: {
683	  user: { id: string; email: string; stripeCustomerId: string | null };
684	  amountCents: number;
685	  hostname: string;
686	  serverId: string;
687	}): Promise<string | null> {
688	  if (!stripeConfigured()) return null;
689	  const amount = Math.max(STRIPE_MIN_CENTS, Math.round(opts.amountCents));
690	  if (amount <= 0) return null;
691	  const base = appBase();
692	  try {
693	    const session = await stripe().checkout.sessions.create({
694	      mode: "payment",
695	      ...(opts.user.stripeCustomerId
696	        ? { customer: opts.user.stripeCustomerId }
697	        : { customer_email: opts.user.email }),
698	      line_items: [
699	        {
700	          price_data: {
701	            currency: "usd",
702	            product_data: {
703	              name: `Nxeon renewal — ${opts.hostname}`,
704	              description:
705	                "Settles the outstanding renewal balance. Added to your Nxeon wallet and applied to this renewal automatically.",
706	            },
707	            unit_amount: amount,
708	          },
709	          quantity: 1,
710	        },
711	      ],
712	      metadata: { nxeonUserId: opts.user.id },
713	      success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
714	      cancel_url: `${base}/dashboard/servers/${opts.serverId}`,
715	    });
716	    return session.url;
717	  } catch (e) {
718	    console.error("[cards] could not create outstanding-balance checkout", e);
719	    return null;
720	  }
721	}
