723	/**
724	 * Cancel a PaymentIntent, but only while it is still unconfirmed — captured money
725	 * is never touched. Best-effort throughout: an uncancelled intent is inert unless
726	 * something confirms it, and nothing in this codebase ever does.
727	 */
728	async function cancelIfUnconfirmed(paymentIntentId: string): Promise<void> {
729	  try {
730	    const pi = await stripe().paymentIntents.retrieve(paymentIntentId);
731	    if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
732	      await stripe().paymentIntents.cancel(paymentIntentId);
733	    }
734	  } catch {
735	    /* best-effort */
736	  }
737	}
