739	/**
740	 * Clean up an abandoned 3-D Secure challenge once its period has been paid another
741	 * way (usually the hosted link).
742	 *
743	 * A leftover `requires_action` intent is a loaded gun: anything that later confirms
744	 * it takes a second payment for a period that is already settled.
745	 */
746	export async function cancelPendingChargeForMarker(
747	  customerId: string | null,
748	  marker: string,
749	): Promise<void> {
750	  if (!customerId || !stripeConfigured()) return;
751	  try {
752	    const list = await stripe().paymentIntents.list({ customer: customerId, limit: 25 });
753	    for (const pi of list.data) {
754	      if (pi.metadata?.nxeonChargeKey !== marker) continue;
755	      if (pi.status === "requires_action" || pi.status === "requires_confirmation") {
756	        await cancelIfUnconfirmed(pi.id);
757	      }
758	    }
759	  } catch {
760	    /* best-effort */
761	  }
762	}
