35	/**
36	 * Refund a customer. When the top-up can be traced back to a Stripe Checkout
37	 * session (its wallet ledger row carries `Stripe payment (cs_...)`) and Stripe
38	 * is configured, the money is returned to the original card via the recovered
39	 * PaymentIntent. Otherwise we fall back to a **wallet-only** refund which simply
40	 * debits the wallet balance and records the ledger entry.
41	 *
42	 * Safety: the wallet is never driven below zero — for a wallet-only refund we
43	 * require sufficient balance; for a Stripe refund of already-spent funds we
44	 * decrement only what remains (the rest is a real-cash write-off) and note it.
45	 */
46	export async function refundPayment(
47	  _prev: unknown,
48	  formData: FormData
49	): Promise<{ error?: string; message?: string }> {
50	  const admin = await requireArea("billing");
51	
52	  const userId = String(formData.get("userId") ?? "");
53	  const reason = String(formData.get("reason") ?? "").trim().slice(0, 200);
54	  const cents = parseAmountCents(formData.get("amount"));
55	  // The invoice this refund is FOR. The UI has always rendered the control under a
56	  // heading naming one invoice, pre-filled with that invoice's total — but the id
57	  // was never sent, so the action guessed its Stripe target as "most recent top-up,
58	  // any amount". Refunding a $24 March invoice therefore issued $24 against the
59	  // customer's $200 July top-up, left the invoice PAID, and invited the next admin
60	  // to refund it all over again.
61	  const invoiceId = String(formData.get("invoiceId") ?? "").trim();
62	
63	  if (!userId) return { error: "Missing customer." };
64	  if (cents === null || cents < 0) return { error: "Enter a positive refund amount (max $50,000)." };
65	
66	  const user = await db.user.findUnique({ where: { id: userId } });
67	  if (!user) return { error: "Customer not found." };
68	
69	  // Resolve and validate the target invoice when one was supplied.
70	  let invoice = null as Awaited<ReturnType<typeof db.invoice.findUnique>>;
71	  if (invoiceId) {
72	    invoice = await db.invoice.findUnique({ where: { id: invoiceId } });
73	    if (!invoice) return { error: "Invoice not found." };
74	    if (invoice.userId !== userId) return { error: "That invoice belongs to a different customer." };
75	    const alreadyRefunded = invoice.refundedCents ?? 0;
76	    const refundable = Math.max(0, invoice.amountCents - alreadyRefunded);
77	    if (refundable === 0) {
78	      return { error: `Invoice already fully refunded ($${(alreadyRefunded / 100).toFixed(2)}).` };
79	    }
80	    if (cents > refundable) {
81	      return {
82	        error: `That exceeds what's left on this invoice — $${(refundable / 100).toFixed(2)} refundable ($${(alreadyRefunded / 100).toFixed(2)} already refunded).`,
83	      };
84	    }
85	  }
86	
87	  // --- Route the refund back to the ORIGINAL card for this charge ---
88	  let method: "stripe" | "wallet" = "wallet";
89	  let stripeRefundId: string | null = null;
90	  if (stripeConfigured()) {
91	    // Prefer the charge that actually paid THIS invoice; only fall back to the
92	    // latest top-up when no invoice was specified (the standalone refund form).
93	    const tx = await db.walletTransaction.findFirst({
94	      where: invoice
95	        ? {
96	            userId,
97	            description: { contains: "Stripe payment (cs_" },
98	            createdAt: { lte: invoice.paidAt ?? invoice.createdAt },
99	          }
100	        : { userId, description: { contains: "Stripe payment (cs_" } },
101	      orderBy: { createdAt: "desc" },
102	    });
103	    const sessionId = sessionIdFrom(tx?.description);
104	    if (sessionId) {
105	      try {
106	        const session = await stripe().checkout.sessions.retrieve(sessionId);
107	        const pi =
108	          typeof session.payment_intent === "string"
109	            ? session.payment_intent
110	            : session.payment_intent?.id;
111	        if (pi) {
112	          // Idempotency key derived from the target and amount: two submits (two
113	          // tabs, or a retry after a gateway timeout) previously issued TWO real
114	          // Stripe refunds and two ledger debits, since the button was only
115	          // disabled while pending.
116	          const refund = await stripe().refunds.create(
117	            { payment_intent: pi, amount: cents },
118	            { idempotencyKey: `refund:${invoiceId || userId}:${pi}:${cents}` }
119	          );
120	          stripeRefundId = refund.id;
121	          method = "stripe";
122	        }
123	      } catch {
124	        // Stripe refund failed / not refundable — fall back to wallet-only.
125	        method = "wallet";
126	      }
127	    }
128	  }
129	
130	  const available = Math.max(0, user.balanceCents);
131	  const walletDebit = Math.min(cents, available);
132	  if (method === "wallet" && walletDebit < cents) {
133	    return {
134	      error:
135	        "Insufficient wallet balance for a wallet-only refund. Use a negative balance adjustment to force it.",
136	    };
137	  }
138	
139	  const writeOff = cents - walletDebit; // real cash returned that the wallet couldn't cover
140	  const noteBits = [
141	    method === "stripe" ? `Stripe refund ${stripeRefundId}` : "wallet-only refund",
142	    invoice ? `invoice ${invoice.number ?? invoice.id}` : null,
143	    reason,
144	  ].filter(Boolean);
145	  const description = `Refund — ${noteBits.join(" · ")}`;
146	
147	  await db.$transaction(async (tx) => {
148	    if (walletDebit > 0) {
149	      await tx.user.update({
150	        where: { id: userId },
151	        data: { balanceCents: { decrement: walletDebit } },
152	      });
153	    }
154	    // The ledger row must equal the ACTUAL balance change. It used to record the
155	    // full refund (-cents) while the balance only fell by what was available, so a
156	    // $50 card refund against a $5 wallet left history and balance disagreeing by
157	    // $45 permanently. The uncovered remainder is a real-cash write-off and gets
158	    // its own zero-balance-effect line, so the story is legible without lying
159	    // about the arithmetic.
160	    if (walletDebit > 0) {
161	      await tx.walletTransaction.create({
162	        data: { userId, amountCents: -walletDebit, description },
163	      });
164	    }
165	    if (writeOff > 0) {
166	      await tx.walletTransaction.create({
167	        data: {
168	          userId,
169	          amountCents: 0,
170	          description:
171	            `Write-off — $${(writeOff / 100).toFixed(2)} of this refund was returned to the card ` +
172	            `beyond the wallet balance, so no wallet deduction applies to that portion. ` +
173	            noteBits.join(" · "),
174	        },
175	      });
176	    }
177	    // Mark the invoice so it cannot be silently refunded twice, and so it stops
178	    // reading PAID. Nothing in the codebase set REFUNDED before this.
179	    if (invoice) {
180	      const total = (invoice.refundedCents ?? 0) + cents;
181	      await tx.invoice.update({
182	        where: { id: invoice.id },
183	        data: {
184	          refundedCents: total,
185	          ...(total >= invoice.amountCents ? { status: "REFUNDED" as const } : {}),
186	        },
187	      });
188	    }
189	  });
190	
191	  await audit(
192	    admin.id,
193	    "billing.refund",
194	    `user=${user.email} $${(cents / 100).toFixed(2)} via ${method}${
195	      stripeRefundId ? ` (${stripeRefundId})` : ""
196	    }`
197	  );
198	  revalidatePath("/admin/billing");
199	  revalidatePath(`/admin/users/${userId}`);
200	  revalidatePath("/dashboard/billing");
201	
202	  const dollars = `$${(cents / 100).toFixed(2)}`;
203	  return {
204	    message:
205	      method === "stripe"
206	        ? `Refunded ${dollars} to the customer's card (Stripe ${stripeRefundId}).`
207	        : `Refunded ${dollars} to the wallet balance.`,
208	  };
209	}
