211	/**
212	 * Manual +/- balance adjustment (credit or debit). A negative amount is the one
213	 * explicit case allowed to drive the balance below zero (e.g. clawing back a
214	 * mistaken credit); positive adjustments simply top the wallet up.
215	 */
216	export async function adjustBalance(
217	  _prev: unknown,
218	  formData: FormData
219	): Promise<{ error?: string; message?: string }> {
220	  const admin = await requireArea("billing");
221	
222	  const userId = String(formData.get("userId") ?? "");
223	  const reason = String(formData.get("reason") ?? "").trim().slice(0, 200);
224	  const cents = parseAmountCents(formData.get("amount"));
225	
226	  if (!userId) return { error: "Missing customer." };
227	  if (cents === null) return { error: "Enter a non-zero amount (max ±$50,000)." };
228	
229	  const user = await db.user.findUnique({ where: { id: userId } });
230	  if (!user) return { error: "Customer not found." };
231	
232	  const description = `Admin balance adjustment${reason ? ` — ${reason}` : ""}`;
233	  await db.$transaction([
234	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
235	    db.walletTransaction.create({ data: { userId, amountCents: cents, description } }),
236	  ]);
237	
238	  await audit(
239	    admin.id,
240	    "billing.adjust_balance",
241	    `user=${user.email} ${cents >= 0 ? "+" : "−"}$${(Math.abs(cents) / 100).toFixed(2)}`
242	  );
243	  revalidatePath("/admin/billing");
244	  revalidatePath(`/admin/users/${userId}`);
245	  revalidatePath("/dashboard/billing");
246	
247	  const dollars = `$${(Math.abs(cents) / 100).toFixed(2)}`;
248	  return { message: `${cents >= 0 ? "Credited" : "Debited"} ${dollars}. New balance applied.` };
249	}
