251	/**
252	 * Bulk-void a set of open/unpaid invoices. Paid invoices are skipped (they must
253	 * be refunded instead) and already-void ones are ignored. Returns counts.
254	 */
255	export async function bulkVoidInvoices(
256	  ids: string[]
257	): Promise<{ voided: number; skipped: number }> {
258	  const admin = await requireArea("billing");
259	  const unique = [...new Set((ids ?? []).filter(Boolean))].slice(0, 500);
260	  if (unique.length === 0) return { voided: 0, skipped: 0 };
261	
262	  const invoices = await db.invoice.findMany({ where: { id: { in: unique } } });
263	  const voidable = invoices.filter((i) => i.status === "OPEN" || i.status === "REFUNDED");
264	
265	  if (voidable.length > 0) {
266	    await db.invoice.updateMany({
267	      where: { id: { in: voidable.map((i) => i.id) } },
268	      data: { status: "VOID", paidAt: null },
269	    });
270	  }
271	
272	  await audit(admin.id, "billing.bulk_void", `${voidable.length} voided of ${unique.length}`);
273	  revalidatePath("/admin/invoices");
274	  revalidatePath("/dashboard/invoices");
275	  return { voided: voidable.length, skipped: unique.length - voidable.length };
276	}
