278	/**
279	 * Bulk-suspend clients. Suspend is a clients-area capability, so this gates on
280	 * "clients" rather than "billing". The acting admin is never suspended.
281	 */
282	export async function bulkSuspendUsers(
283	  ids: string[]
284	): Promise<{ suspended: number }> {
285	  const admin = await requireArea("clients");
286	  const unique = [...new Set((ids ?? []).filter(Boolean))]
287	    .filter((id) => id !== admin.id)
288	    .slice(0, 500);
289	  if (unique.length === 0) return { suspended: 0 };
290	
291	  const res = await db.user.updateMany({
292	    where: { id: { in: unique }, role: { not: "ADMIN" } },
293	    data: { suspended: true },
294	  });
295	
296	  await audit(admin.id, "clients.bulk_suspend", `${res.count} suspended`);
297	  revalidatePath("/admin/users");
298	  return { suspended: res.count };
299	}
