563	export async function topUp(prev: any, formData: FormData): Promise<{ error?: string }> {
564	  const user = await requireUser();
565	  // Spend/credit path: block while impersonating so an admin can't mint or move
566	  // a customer's balance on their behalf.
567	  await assertNotImpersonating();
568	  // Security: never mint free wallet balance in production. The demo gateway that
569	  // credits without a real payment is only ever acceptable in non-production, and
570	  // is refused outright when NODE_ENV === "production" regardless of Stripe.
571	  if (process.env.NODE_ENV === "production") {
572	    return { error: "Please add funds with a card via the secure checkout." };
573	  }
574	  // Once Stripe is configured, the demo gateway is hard-disabled — top-ups must
575	  // go through Checkout.
576	  const { stripeConfigured } = await import("./stripe");
577	  if (stripeConfigured()) {
578	    return { error: "Please add funds with a card via the secure checkout." };
579	  }
580	  // Throttle demo top-ups per user+IP to prevent rapid free-credit minting.
581	  const topupHdrs = await headers();
582	  const topupIp = (topupHdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
583	  const topupRl = checkRateLimit(`topup:${user.id}:${topupIp}`, { max: 10, windowMs: 60 * 60 * 1000 });
584	  if (!topupRl.ok) {
585	    return { error: `Too many top-up attempts. Try again in ${topupRl.retryAfterSec}s.` };
586	  }
587	  const amount = Number(formData.get("amount"));
588	  if (!Number.isFinite(amount) || amount < 1 || amount > 1000) {
589	    return { error: "Amount must be between $1 and $1000." };
590	  }
591	  const cents = Math.round(amount * 100);
592	  // Enforce the admin-configured minimum top-up (`min_topup_cents`, default 500).
593	  const minTopup = await getSettingInt("min_topup_cents", 500);
594	  if (cents < minTopup) {
595	    return { error: `Minimum top-up is $${(minTopup / 100).toFixed(2)}.` };
596	  }
597	
598	  // Optional promo code: applied via the COUPON_COOKIE the billing CouponField
599	  // sets. applyCouponToTopup re-validates for this user against the real amount.
