836	  if (!serverId || !Number.isFinite(days) || days === 0 || Math.abs(days) > 365) {
837	    return { error: "Days must be between -365 and 365." };
838	  }
839	  const server = await db.server.findUnique({ where: { id: serverId } });
840	  if (!server) return { error: "Server not found." };
841	  const base = server.expiresAt ? server.expiresAt.getTime() : Date.now();
842	
843	  // ─── EXPIRESAT INTEGRITY ────────────────────────────────────────────────────
844	  // The whole proration model rests on "every month between now and `expiresAt` is
845	  // a month the customer has actually bought" (see lib/proration.ts
846	  // remainingMonths). This action moves `expiresAt` by up to a year per call, with
847	  // no call limit and no payment — so before the persisted rate existed, an admin
848	  // goodwill gift of 12 months was directly convertible to cash: downgrade the
849	  // gifted server and the prorated credit paid out real wallet money for months
850	  // nobody had ever been charged for. Admin-only, so never a self-service exploit,
851	  // but a support agent clicking "extend" was minting refundable balance.
852	  //
853	  // SEMANTICS CHOSEN: gifted months are recorded as sold at 100% off, and blended
854	  // into the rate the existing months are on. That is the honest reading of a gift
855	  // — those months cost the customer nothing, so nothing may prorate out of them —
856	  // and it is exact rather than blunt: the blend leaves the CASH VALUE of the
857	  // remaining window completely unchanged, so a customer who paid for 12 months and
858	  // was gifted a 13th still gets back precisely what those 12 paid months are worth
859	  // on a downgrade. Zeroing the whole term instead would confiscate what they paid;
860	  // leaving the rate alone is the money printer. Repeated gifts only ever dilute
861	  // toward 100, so no number of calls can raise the payout.
862	  //
863	  // A NEGATIVE `days` removes months rather than adding them, so there is nothing
864	  // to blend in: the customer keeps the rate they bought at over a shorter window,
865	  // which strictly reduces any future credit. Blending negative months would push
866	  // the rate the other way and over-credit what is left.
867	  const gifted = days > 0;
868	  const termPromoPercent = gifted
869	    ? prorateBlendPercent({
870	        currentPercent: resolveTermPromoPercent(server.termPromoPercent),
871	        currentMonths: remainingMonths(server.expiresAt, Date.now()),
872	        addedPercent: 100, // gifted: no cash changed hands for these months
873	        addedMonths: (days * 86400_000) / MS_PER_AVG_MONTH,
874	      })
875	    : resolveTermPromoPercent(server.termPromoPercent);
876	
877	  await db.server.update({
878	    where: { id: serverId },
879	    data: { expiresAt: new Date(base + days * 86400_000), termPromoPercent },
880	  });
881	  await audit(
882	    admin.id,
883	    "admin.extend_server",
884	    `${serverId} ${days}d${gifted ? ` gifted (rate basis ${server.termPromoPercent ?? "null"}% -> ${termPromoPercent}% off)` : ""}`,
885	  );
886	  revalidatePath("/admin/subscriptions");
887	  return {};
888	}
