134	/**
135	 * Move a server to a SMALLER (cheaper) plan. CPU/RAM can shrink freely, but the
136	 * disk can NOT shrink on the hypervisor, so we require the target plan's disk to
137	 * be >= the current plan's disk (the worker's RESIZE handler hard-fails a shrink
138	 * otherwise). A prorated credit for the price difference over the remaining term
139	 * is returned to the wallet.
140	 */
141	export async function resizeServerDown(
142	  serverId: string,
143	  newPlanId: string
144	): Promise<{ error?: string }> {
145	  const { user, server } = await ownedServer(serverId);
146	
147	  const newPlan = await db.plan.findUnique({ where: { id: newPlanId } });
148	  if (!newPlan?.active) return { error: "Plan not available." };
149	  if (newPlan.id === server.planId) return { error: "Server is already on this plan." };
150	  if (!["RUNNING", "STOPPED"].includes(server.status)) return { error: "Server is busy." };
151	
152	  // This action is downgrades only — upgrades go through resizeServer().
153	  if (newPlan.priceCents >= server.plan.priceCents) {
154	    return { error: "This is not a smaller plan — use the upgrade flow instead." };
155	  }
156	  // Disk can't shrink destructively; block the move rather than lose data.
157	  // Compares PLAN disks on purpose: any purchased `extraDiskGB` is additive to
158	  // both the old and the new plan and is preserved verbatim across the resize, so
159	  // "new plan disk >= old plan disk" is exactly the condition for "effective disk
160	  // does not shrink". Nothing here ever writes extraDiskGB.
161	  if (newPlan.diskGB < server.plan.diskGB) {
162	    return {
163	      error: `Disk can't shrink — ${newPlan.name} has a ${newPlan.diskGB} GB disk but your server uses ${server.plan.diskGB} GB. Pick a smaller plan whose disk is at least ${server.plan.diskGB} GB.`,
164	    };
165	  }
166	
167	  if (await hasInflightJob(serverId)) {
168	    return { error: "Another operation is already in progress on this server." };
169	  }
170	
171	  // Credit at the SAME effective rate the upgrade path charges at (term discount
172	  // plus `server.termPromoPercent`, the rate THIS term was actually sold at) over
173	  // the SAME remaining duration — every month left on `expiresAt`, uncapped,
174	  // exactly as lib/resize.ts charges for. Both directions read that one persisted
175	  // scalar off the same row, which is what makes a round trip net to zero no matter
176	  // what dates the two halves happen on. Until 2026-07-26 the rate came from
177	  // `currentPromo(now)` instead, so a customer could upgrade under the 45% Cyber
178	  // Monday basis and downgrade under the 15% Launch Sale basis and keep the spread
179	  // on every remaining month, once per promo cycle, forever.
180	  //
181	  // The old maths credited the raw LIST-price delta, so it refunded more than the
182	  // customer had ever paid (they bought at the term-discounted, promo-reduced
183	  // price). Pricing both directions through lib/proration.ts fixed the RATE, but
184	  // this line then capped the DURATION at one term while the upgrade side did not,
185	  // which broke the round trip the other way: a customer whose stacked "Renew now"
186	  // had pushed `expiresAt` 36 months out on a 12-month term paid $544.32 to
187	  // upgrade Starter -> Max and got only $181.44 back coming straight down, so the
188	  // platform pocketed $362.88 of months they had genuinely paid for. `expiresAt`
189	  // never advances without payment, so all of those months are owed back. The cap
190	  // argument has been removed from `remainingMonths` outright — the two directions
191	  // now cannot express different durations.
192	  let creditCents = 0;
193	  if (!server.isFree && server.expiresAt) {
194	    creditCents = prorateDowngradeCreditCents({
195	      fromMonthlyCents: server.plan.priceCents,
196	      toMonthlyCents: newPlan.priceCents,
197	      termMonths: server.termMonths,
198	      termPromoPercent: server.termPromoPercent,
199	      monthsRemaining: remainingMonths(server.expiresAt, Date.now()),
200	    });
201	  }
202	
203	  await db.$transaction([
204	    ...(creditCents > 0
205	      ? [
206	          db.user.update({
207	            where: { id: server.userId },
208	            data: { balanceCents: { increment: creditCents } },
209	          }),
210	          db.walletTransaction.create({
211	            data: {
212	              userId: server.userId,
213	              amountCents: creditCents,
214	              description: `Downgrade to ${newPlan.name} (prorated credit) — ${server.hostname}`,
215	            },
216	          }),
217	        ]
218	      : []),
219	    // Record the amount credited on the job so the worker's RESIZE handler can
220	    // REVERSE it (re-debit `payload.prorateCents` from the wallet) if the resize
221	    // terminally fails — the credit is committed here, before the job runs.
222	    //
223	    // DONE, not pending: `reconcileFailedJob` (worker/index.ts) reads both fields
224	    // and claws the credit back on `direction: "down"`, guarded by `debitWallet`
225	    // so it can never drive the balance negative, and idempotent on an audit row
226	    // keyed to this job id. It is called from both terminal-failure paths.
227	    //
228	    // This carried an "INTEGRATION NEEDED" note long after the integration
229	    // landed, and on 2026-07-26 an audit read the note rather than the code and
230	    // reported a live double-credit money bug that does not exist. A stale
231	    // comment claiming work is undone costs real investigation time and, worse,
232	    // invites someone to "fix" a path that is already correct.
233	    db.job.create({
234	      data: {
235	        type: "RESIZE",
236	        serverId,
237	        payload: { planId: newPlan.id, prorateCents: creditCents, direction: "down" } as any,
238	      },
239	    }),
240	    db.auditLog.create({
241	      data: {
242	        userId: user.id,
243	        action: "server.resize_down",
244	        detail: `${serverId} -> ${newPlan.slug} credit=${creditCents}`,
245	      },
246	    }),
247	  ]);
248	
249	  revalidatePath(`/dashboard/servers/${serverId}`);
250	  return {};
251	}
