/** For the confirm route: the disk-expansion intent attached to a paid session, if any. */
export async function getCheckoutDiskExpandIntent(
  sessionId: string,
): Promise<{ userId: string; serverId: string; addGB: number; chargeCents: number } | null> {
  if (!stripeConfigured()) return null;
  try {
    const session = await stripe().checkout.sessions.retrieve(sessionId);
    const userId = session.metadata?.nxeonUserId;
    const raw = session.metadata?.nxeonDiskExpand;
    if (!userId || !raw || session.payment_status !== "paid") return null;
    const parsed = JSON.parse(raw) as { serverId: string; addGB: number; chargeCents: number };
    return { userId, serverId: parsed.serverId, addGB: parsed.addGB, chargeCents: parsed.chargeCents };
  } catch {
    return null;
  }
}

/** For the confirm route: the resize intent attached to a paid session, if any. */
export async function getCheckoutResizeIntent(
  sessionId: string,
): Promise<{ userId: string; serverId: string; planId: string; chargeCents: number } | null> {
  if (!stripeConfigured()) return null;
  try {
    const session = await stripe().checkout.sessions.retrieve(sessionId);
    const userId = session.metadata?.nxeonUserId;
    const raw = session.metadata?.nxeonResize;
    if (!userId || !raw || session.payment_status !== "paid") return null;
    const parsed = JSON.parse(raw) as { serverId: string; planId: string; chargeCents: number };
    return { userId, serverId: parsed.serverId, planId: parsed.planId, chargeCents: parsed.chargeCents };
  } catch {
    return null;
  }
}

/**
 * For the confirm route: the order intent attached to a paid session, if any,
 * together with the price the order was SOLD at.
 *
 * `sold` is null only for sessions created before `nxeonOrderPrice` existed (or
 * for a metadata value that does not parse cleanly). Those fall back to a fresh
 * quote — the old, re-pricing behaviour — because there is genuinely nothing else
 * to settle them against; every session created from now on carries its price.
 */
export async function getCheckoutOrderIntent(
  sessionId: string,
): Promise<{ userId: string; intent: OrderIntent; sold: OrderPrice | null } | null> {
  if (!stripeConfigured()) return null;
  try {
    const session = await stripe().checkout.sessions.retrieve(sessionId);
    const userId = session.metadata?.nxeonUserId;
    const raw = session.metadata?.nxeonOrder;
    if (!userId || !raw || session.payment_status !== "paid") return null;
    return {
      userId,
      intent: JSON.parse(raw) as OrderIntent,
      sold: parseOrderPrice(session.metadata?.nxeonOrderPrice),
    };
  } catch {
    return null;
  }
}

