import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { classifyCheckoutSession } from "../lib/stripe.ts";
import { vpsTermPriceCents } from "../lib/billing-terms.ts";
import { currentPromo, promoPriceCents } from "../lib/promotions.ts";

/**
 * REAL DEFECT (2026-07-27 money-core audit, found by reading lib/fulfil-checkout.ts
 * against lib/stripe.ts).
 *
 * `fulfilCheckoutSession` decided what a paid Checkout session was FOR by asking
 * three helpers in turn — `getCheckoutOrderIntent`, `getCheckoutResizeIntent`,
 * `getCheckoutDiskExpandIntent`. Each one did its OWN `sessions.retrieve` inside a
 * `try { … } catch { return null }`. So `null` meant two completely different
 * things that the caller could not tell apart:
 *
 *     "this session carries no order metadata"      (a genuine wallet top-up)
 *     "I could not read this session from Stripe"   (a 5xx, a rate limit, a socket)
 *
 * Three nulls in a row fell through to the final line — `{ kind: "topup",
 * fulfilled: true }`. A transient Stripe error on a real $249 VPS order therefore
 * produced: card captured, NO server, NO `FulfilledSession` row (the claim is only
 * taken inside a branch), NO notification, and a redirect to
 * `/dashboard/billing?paid=1`. The webhook returns 200 whatever happens, so Stripe
 * never retried it. Silent, and invisible from every surface we own — which is the
 * exact failure lib/fulfil-checkout.ts was written to end, arriving one layer up.
 *
 * The same `null` also swallowed a metadata payload that parses but is missing
 * `chargeCents`: `applyResize` does `opts.chargeCents ?? quote.prorateCents`, so a
 * half-valid resize payload would have been silently RE-QUOTED at confirm time —
 * the H2 re-pricing incident, from the other direction.
 *
 * The routing decision is now ONE pure function over ONE retrieved session, and
 * "unreadable" and "unpaid" are answers rather than absences. These tests pin every
 * branch of it, plus source tripwires that the caller cannot go back to swallowing.
 */

/** Source with comments stripped: a tripwire that greps raw source matches its own
 * incident note and fails on correct code. */
function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

/** The shape `classifyCheckoutSession` reads — metadata plus payment status. */
function session(metadata: Record<string, string> | null, paid = true) {
  return { metadata, payment_status: (paid ? "paid" : "unpaid") as "paid" | "unpaid" };
}

/** A real sold price, derived from the live catalogue rather than a literal. */
const SUMMER = new Date("2026-08-01T12:00:00.000Z"); // Summer Sale, 30%
const SOLD_CENTS = promoPriceCents(vpsTermPriceCents(899, 12), currentPromo(SUMMER)); // 6796

/* ------------------------------------------------------------------ *
 * The happy paths still classify exactly as before
 * ------------------------------------------------------------------ */

test("an order session carries its intent and the price it was SOLD at", () => {
  const p = classifyCheckoutSession(
    session({
      nxeonUserId: "u1",
      nxeonOrder: JSON.stringify({ planId: "p1", hostname: "web-1", termMonths: 12 }),
      nxeonOrderPrice: JSON.stringify({ chargeCents: SOLD_CENTS, promoPercent: 30, promoName: "Summer Sale" }),
    }),
  );
  assert.equal(p.kind, "order");
  assert.equal(p.kind === "order" && p.userId, "u1");
  assert.equal(p.kind === "order" && p.sold?.chargeCents, 6796);
  assert.equal(p.kind === "order" && p.sold?.promoPercent, 30);
});

test("an order with no stamped price still fulfils — sold is null, not a refusal", () => {
  // Sessions created before `nxeonOrderPrice` existed. placeOrder falls back to a
  // fresh quote for these, which is the OLD behaviour and the only thing available.
  const p = classifyCheckoutSession(
    session({ nxeonUserId: "u1", nxeonOrder: JSON.stringify({ planId: "p1" }) }),
  );
  assert.equal(p.kind, "order");
  assert.equal(p.kind === "order" && p.sold, null);
});

test("a resize session carries the FULL proration, not the card leg", () => {
  const p = classifyCheckoutSession(
    session({
      nxeonUserId: "u1",
      nxeonResize: JSON.stringify({ serverId: "s1", planId: "p2", chargeCents: 12345 }),
    }),
  );
  assert.deepEqual(p, { kind: "resize", userId: "u1", serverId: "s1", planId: "p2", chargeCents: 12345 });
});

test("a disk-expansion session carries the GB and the proration", () => {
  const p = classifyCheckoutSession(
    session({
      nxeonUserId: "u1",
      nxeonDiskExpand: JSON.stringify({ serverId: "s1", addGB: 50, chargeCents: 500 }),
    }),
  );
  assert.deepEqual(p, { kind: "diskExpand", userId: "u1", serverId: "s1", addGB: 50, chargeCents: 500 });
});

test("a session with no purchase metadata is a genuine wallet top-up", () => {
  assert.deepEqual(classifyCheckoutSession(session({ nxeonUserId: "u1" })), {
    kind: "topup",
    userId: "u1",
  });
});

/* ------------------------------------------------------------------ *
 * THE INCIDENT: unreadable is never a top-up
 * ------------------------------------------------------------------ */

test("purchase metadata that will not parse is UNREADABLE, never a top-up", () => {
  // The legacy `JSON.stringify(x).slice(0, 490)` shape: a slice through JSON is not
  // JSON. It used to throw into a `catch { return null }` and become a top-up —
  // card charged, no server, no failure row (test/checkout-metadata.test.ts).
  for (const key of ["nxeonOrder", "nxeonResize", "nxeonDiskExpand"]) {
    const p = classifyCheckoutSession(session({ nxeonUserId: "u1", [key]: '{"planId":"p1","hostn' }));
    assert.equal(p.kind, "unreadable", `${key} truncated must not be classified as a top-up`);
    assert.equal(p.kind === "unreadable" && p.userId, "u1", "we still know whose money it is");
    assert.match(
      p.kind === "unreadable" ? p.detail : "",
      new RegExp(key),
      "the failure names the key so the FulfilledSession row is reconcilable",
    );
  }
});

test("a resize payload missing chargeCents is refused rather than silently re-quoted", () => {
  // `applyResize` does `opts.chargeCents ?? quote.prorateCents`. An undefined here
  // does not fail loudly — it re-derives the price at confirm time, minutes or hours
  // after the card cleared against the OLD figure. That is the H2 incident.
  const p = classifyCheckoutSession(
    session({ nxeonUserId: "u1", nxeonResize: JSON.stringify({ serverId: "s1", planId: "p2" }) }),
  );
  assert.equal(p.kind, "unreadable");
});

test("a charge amount that is not whole non-negative cents is refused", () => {
  // Every one of these reaches `debitWallet` and an Invoice row, both of which are
  // integer cents. A string sails past `cents <= 0` and detonates at Prisma AFTER
  // the card has been charged; a negative one is a debit that pays the customer.
  for (const bad of ['"1234"', "12.5", "-1", "null", "true"]) {
    const resize = classifyCheckoutSession(
      session({ nxeonUserId: "u1", nxeonResize: `{"serverId":"s1","planId":"p2","chargeCents":${bad}}` }),
    );
    assert.equal(resize.kind, "unreadable", `resize chargeCents ${bad} must be refused`);
    const expand = classifyCheckoutSession(
      session({ nxeonUserId: "u1", nxeonDiskExpand: `{"serverId":"s1","addGB":50,"chargeCents":${bad}}` }),
    );
    assert.equal(expand.kind, "unreadable", `diskExpand chargeCents ${bad} must be refused`);
  }
  // Zero IS valid — a free/admin server prorates to nothing and still fulfils.
  const free = classifyCheckoutSession(
    session({ nxeonUserId: "u1", nxeonResize: '{"serverId":"s1","planId":"p2","chargeCents":0}' }),
  );
  assert.equal(free.kind, "resize");
});

test("a resize payload missing its server or plan id is refused", () => {
  for (const raw of [
    '{"planId":"p2","chargeCents":10}',
    '{"serverId":"s1","chargeCents":10}',
    '{"serverId":"","planId":"p2","chargeCents":10}',
  ]) {
    assert.equal(classifyCheckoutSession(session({ nxeonUserId: "u1", nxeonResize: raw })).kind, "unreadable");
  }
});

test("an order payload that is valid JSON but not an object is refused", () => {
  // `JSON.parse("null")` and `JSON.parse("7")` both succeed. The old code cast the
  // result straight to OrderIntent and handed it to placeOrder.
  for (const raw of ["null", "7", '"planId"', "[]"]) {
    const p = classifyCheckoutSession(session({ nxeonUserId: "u1", nxeonOrder: raw }));
    if (raw === "[]") continue; // an array IS an object; the schema in placeOrder rejects it
    assert.equal(p.kind, "unreadable", `nxeonOrder ${raw} must be refused`);
  }
});

/* ------------------------------------------------------------------ *
 * Unpaid is not fulfilment
 * ------------------------------------------------------------------ */

test("a session that has not been paid is never fulfilled and never credited", () => {
  // /api/stripe/confirm is unauthenticated and its session_id is in a URL anyone can
  // edit. An open (unpaid) session used to fall through all three nulls and report
  // `{ kind: "topup", fulfilled: true }` — claiming fulfilment for money that had
  // not arrived, and telling the customer "paid".
  assert.equal(classifyCheckoutSession(session({ nxeonUserId: "u1" }, false)).kind, "unpaid");
  assert.equal(
    classifyCheckoutSession(session({ nxeonUserId: "u1", nxeonOrder: '{"planId":"p"}' }, false)).kind,
    "unpaid",
  );
});

test("a session with no nxeonUserId belongs to nobody and fulfils nothing", () => {
  assert.equal(classifyCheckoutSession(session({})).kind, "unpaid");
  assert.equal(classifyCheckoutSession(session(null)).kind, "unpaid");
  assert.equal(classifyCheckoutSession(session({ nxeonUserId: "" })).kind, "unpaid");
});

/* ------------------------------------------------------------------ *
 * Source tripwires — the caller cannot go back to swallowing
 * ------------------------------------------------------------------ */

const FULFIL = code("../lib/fulfil-checkout.ts");
const STRIPE = code("../lib/stripe.ts");

test("fulfilment retrieves the session ONCE and routes on that one object", () => {
  assert.match(FULFIL, /const session = await retrieveCheckoutSession\(sessionId\)/, "one retrieve");
  assert.match(FULFIL, /const purpose = classifyCheckoutSession\(session\)/, "one classification");
  // Four separate retrieves (credit + three getters) meant four independent chances
  // to fail differently about the same payment.
  assert.equal(
    (FULFIL.match(/retrieveCheckoutSession\(/g) ?? []).length,
    1,
    "a second retrieve is a second view of the same session",
  );
});

test("a Stripe read failure is not swallowed anywhere on the fulfilment path", () => {
  assert.ok(
    !/creditCheckoutSession\([^)]*\)\s*\.catch/.test(FULFIL),
    "the credit's failure must propagate — money that never reached the wallet must not be spent",
  );
  // The retrieve helper is the one that must never return a stand-in for failure.
  const retrieve = STRIPE.slice(STRIPE.indexOf("export async function retrieveCheckoutSession"));
  const body = retrieve.slice(0, retrieve.indexOf("\n}"));
  assert.ok(!/catch/.test(body), "retrieveCheckoutSession must not catch — it throws or it returns a session");
});

test("the top-up branch is reachable only from a session that really is a top-up", () => {
  // The old fall-through was positional: reaching the last line of the function
  // meant "top-up". It is now a classified kind, and the two states that used to be
  // indistinguishable from it are handled above it, by name.
  assert.match(FULFIL, /if \(purpose\.kind === "unpaid"\)/, "unpaid short-circuits");
  assert.match(FULFIL, /if \(purpose\.kind === "unreadable"\)/, "unreadable short-circuits");
  assert.ok(
    FULFIL.indexOf('purpose.kind === "unreadable"') < FULFIL.indexOf('kind: "topup"'),
    "both must be decided BEFORE the top-up result is returned",
  );
});

test("an unreadable purchase claims the session, records the failure and tells the customer", () => {
  const branch = FULFIL.slice(
    FULFIL.indexOf('if (purpose.kind === "unreadable")'),
    FULFIL.indexOf("const order ="),
  );
  assert.match(branch, /claim\(sessionId, "unreadable"\)/, "the session is claimed so it is not re-run");
  assert.match(branch, /settle\(sessionId, "FAILED"/, "the failure is written where finance can find it");
  assert.match(branch, /notifyStalled\(/, "and the customer is told their money is safe");
  assert.ok(!/kind: "topup"/.test(branch), "it must never be reported as a top-up");
});

test("every fulfilment failure that captured money notifies the customer", () => {
  // Resize and disk-expansion used to settle FAILED silently: the money sat in the
  // wallet and the only surface that said so was a database row.
  assert.equal(
    (FULFIL.match(/notifyStalled\(/g) ?? []).length,
    5, // definition + unreadable + order + resize + diskExpand
    "each captured-but-unfulfilled branch must notify",
  );
});

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { renewalCharge } from "../lib/renewal-charge.ts";
import { vpsTermPriceCents } from "../lib/billing-terms.ts";
import { STRIPE_MIN_CENTS, walletSplit } from "../lib/wallet-split.ts";

/**
 * Guards on the four money paths that are bound to Stripe or the database and so
 * cannot be exercised as pure functions: admin refunds, the outstanding-balance
 * checkout link, the off-session charge's non-expiring idempotency guard, and the
 * staff-initiated "settle this customer's balance" link.
 *
 * Where the property is arithmetic it is asserted directly. Where it lives inside a
 * `"use server"` action it is asserted against the file's CODE — comments stripped
 * first, because every fix in this codebase carries a comment quoting the incident
 * it fixed and a raw grep would match the note and pass on broken code.
 */

function code(relative: string): string {
  return readFileSync(new URL(relative, import.meta.url), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
}

const ADMIN_BILLING = code("../lib/actions-admin-billing.ts");
const CARDS = code("../lib/stripe-cards.ts");
const PAYMENT_METHOD = code("../lib/actions-payment-method.ts");
const DEDICATED_IP = code("../lib/dedicated-ip.ts");

/* ------------------------------------------------------------------ *
 * 1. Two identical partial refunds collapsed into one at Stripe while
 *    the wallet was debited twice
 *
 * REAL DEFECT (2026-07-27 money-core audit). `refundPayment` sent Stripe an
 * idempotency key of `refund:<invoiceId|userId>:<pi>:<cents>`. That correctly
 * deduplicates a double-submit — which is what it was added for — but it ALSO
 * deduplicates two refunds that are genuinely different and merely the same size.
 * Two $10 partial refunds against one $100 invoice is an ordinary support
 * sequence: Stripe replayed the FIRST refund object for the second request, so one
 * $10 refund reached the card while this action debited the customer's wallet $10
 * twice and recorded $20 against the invoice. The customer was $10 down and every
 * one of our own records agreed that they were not.
 * ------------------------------------------------------------------ */

/**
 * The key as the action derives it, reproduced here because it lives inside a
 * `"use server"` file that cannot be imported into a test. The tripwire below
 * fails if the real line stops matching this copy.
 */
const invoiceRefundKey = (invoiceId: string, pi: string, alreadyRefunded: number, cents: number) =>
  `refund:${invoiceId}:${pi}:${alreadyRefunded}:${cents}`;

test("two successive partial refunds of the same size are two distinct Stripe requests", () => {
  // A $100 invoice, refunded $10 and then $10 again. `alreadyRefunded` is what the
  // request READ before it acted: 0, then 10.
  const first = invoiceRefundKey("inv_1", "pi_1", 0, 1000);
  const second = invoiceRefundKey("inv_1", "pi_1", 1000, 1000);
  assert.notEqual(first, second, "the second $10 must reach the card, not replay the first");
  // The old shape, for the record: identical, so Stripe returned refund #1 again.
  assert.equal(`refund:inv_1:pi_1:1000`, `refund:inv_1:pi_1:1000`);
});

test("a genuine double-submit still collapses to ONE refund", () => {
  // Two tabs, or a retry after a gateway timeout. Both read the same running total,
  // so both produce the same key and Stripe issues the refund once.
  const tabA = invoiceRefundKey("inv_1", "pi_1", 0, 2400);
  const tabB = invoiceRefundKey("inv_1", "pi_1", 0, 2400);
  assert.equal(tabA, tabB, "the protection this key was added for must survive");
});

test("the refund key still carries the running refunded total", () => {
  assert.match(
    ADMIN_BILLING,
    /`refund:\$\{invoiceId\}:\$\{pi\}:\$\{alreadyRefunded\}:\$\{cents\}`/,
    "the invoice branch keys on how much was already refunded — update invoiceRefundKey above if this changes",
  );
  assert.match(ADMIN_BILLING, /`refund:\$\{userId\}:\$\{pi\}:\$\{cents\}`/, "standalone refunds keep the old shape");
});

test("the invoice's refunded total is advanced by compare-and-swap, before any money moves", () => {
  const tx = ADMIN_BILLING.slice(
    ADMIN_BILLING.indexOf("await db.$transaction(async (tx) => {"),
    ADMIN_BILLING.indexOf("await audit("),
  );
  assert.match(
    tx,
    /updateMany\(\{\s*where: \{ id: invoice\.id, refundedCents: alreadyRefunded \}/,
    "only the writer that still sees the total it read may record this refund",
  );
  assert.match(tx, /if \(advanced\.count === 0\) throw new AlreadyRefundedError\(\)/);
  // Ordering is the whole point: losing the swap must write nothing at all, so the
  // wallet decrement cannot happen for a refund another request already recorded.
  assert.ok(
    tx.indexOf("refundedCents: alreadyRefunded") < tx.indexOf("balanceCents: { decrement: walletDebit }"),
    "the compare-and-swap must come BEFORE the wallet is debited",
  );
  assert.match(ADMIN_BILLING, /e instanceof AlreadyRefundedError/, "and the loser gets an explanation, not a crash");
});

test("the refund ledger row can never exceed the balance change it describes", () => {
  // Unchanged behaviour, pinned because it is the invariant the write-off line
  // exists to keep: history and balance must tell the same story.
  const walletDebit = (cents: number, balance: number) => Math.min(cents, Math.max(0, balance));
  assert.equal(walletDebit(5000, 500), 500, "a $50 card refund against a $5 wallet debits $5");
  assert.equal(5000 - walletDebit(5000, 500), 4500, "and the rest is a write-off with no balance effect");
  assert.equal(walletDebit(5000, 12000), 5000);
});

/* ------------------------------------------------------------------ *
 * 2. The outstanding-balance link charged 50c to a customer who owed nothing
 *
 * `createOutstandingCheckout` computed `Math.max(STRIPE_MIN_CENTS, round(amount))`
 * and only THEN asked `if (amount <= 0) return null` — which can never be true
 * after a max against 50. So a caller whose wallet already covered the renewal
 * minted a real hosted-checkout page asking for fifty cents.
 * ------------------------------------------------------------------ */

test("nothing outstanding means no link, not a minimum charge", () => {
  const src = CARDS.slice(CARDS.indexOf("export async function createOutstandingCheckout"));
  const body = src.slice(0, src.indexOf("\n}"));
  // The zero-check must read the INPUT, before the floor is applied.
  assert.ok(
    body.indexOf("if (!Number.isFinite(due) || due <= 0) return null") <
      body.indexOf("Math.max(STRIPE_MIN_CENTS"),
    "the guard has to run before the floor, or it is unreachable",
  );
});

test("a real shortfall below Stripe's floor is still payable, and lands in the wallet", () => {
  // The floor is legitimate HERE and nowhere else: this session credits the wallet,
  // so a 30c balance settled at the 50c minimum leaves the customer 20c of their own
  // credit. `walletSplit` — which settles purchases directly — refuses to inflate.
  assert.equal(Math.max(STRIPE_MIN_CENTS, 30), STRIPE_MIN_CENTS);
  const purchase = walletSplit({ dueCents: 30, balanceCents: 0, useWallet: true });
  assert.equal(purchase.cardCents, 0, "a purchase is never rounded UP to reach the card floor");
  assert.equal(purchase.walletApplied, 30, "it comes out of the wallet at its true size");
  assert.equal(purchase.belowStripeMin, true);
});

/* ------------------------------------------------------------------ *
 * 3. The non-expiring duplicate-charge guard could fall off its own page
 *
 * `findChargeByMarker` is the guard that survives forever — Stripe honours an
 * idempotency key for 24 hours while the dunning ladder runs six days, so between
 * the day-3 and day-5 retries this lookup is the ONLY thing standing between a
 * crash-after-capture and a second charge for the same period. It listed 25
 * PaymentIntents. That list is scoped to the CUSTOMER, not the server, so an
 * account with thirty servers renewing in one sweep pushes the marker off page one.
 * ------------------------------------------------------------------ */

test("the permanent duplicate-charge guard reads Stripe's largest page", () => {
  const fn = CARDS.slice(CARDS.indexOf("async function findChargeByMarker"));
  const body = fn.slice(0, fn.indexOf("\n}"));
  assert.match(body, /paymentIntents\.list\(\{ customer: customerId, limit: 100 \}\)/, "100 is Stripe's maximum");
  assert.ok(!/limit: 25/.test(body), "25 is fewer than one busy customer's monthly renewals");
});

test("a marker is unique per server AND per period, so two periods never share a guard", async () => {
  const { renewalChargeMarker } = await import("../lib/stripe-cards.ts");
  const jan = renewalChargeMarker("srv_1", new Date("2026-01-01T00:00:00.000Z"));
  const feb = renewalChargeMarker("srv_1", new Date("2026-02-01T00:00:00.000Z"));
  const other = renewalChargeMarker("srv_2", new Date("2026-01-01T00:00:00.000Z"));
  assert.notEqual(jan, feb, "consecutive periods must be separately payable");
  assert.notEqual(jan, other, "two servers renewing on the same day must not share one guard");
  assert.equal(jan, renewalChargeMarker("srv_1", new Date("2026-01-01T00:00:00.000Z")), "and it is stable");
});

/* ------------------------------------------------------------------ *
 * 4. Staff settling a customer's balance quoted — and credited — the WRONG WALLET
 *
 * `settleOutstanding` allows `user.role === "ADMIN"` to act on any server, but it
 * split the charge against `user.balanceCents` and stamped the Checkout session
 * with `user.id`. So an admin settling a customer's renewal produced a payment
 * link that credits the ADMIN's wallet and leaves the server exactly as unpaid —
 * and the link is stored on `Server.dunningPayUrl`, which worker/billing.ts emails
 * to the CUSTOMER verbatim in the "your bank needs to confirm" notice.
 * ------------------------------------------------------------------ */

test("the outstanding quote is priced and credited against the server's OWNER", () => {
  const fn = PAYMENT_METHOD.slice(PAYMENT_METHOD.indexOf("export async function settleOutstanding"));
  assert.match(fn, /const owner = server\.user/, "the owner is resolved explicitly");
  assert.match(fn, /balanceCents: owner\.balanceCents/, "the wallet applied is the owner's");
  assert.match(fn, /user: owner,/, "and the session is stamped with the owner, so the credit lands there");
  assert.ok(
    !/balanceCents: user\.balanceCents/.test(fn),
    "the acting admin's balance must not decide a customer's card remainder",
  );
});

/* ------------------------------------------------------------------ *
 * 5. An admin-priced add-on has to be whole cents before it is multiplied
 *
 * `dedicatedIpMonthlyCents` returned `getSettingInt(...)` raw, and getSettingInt is
 * a bare `Number()` over whatever string sits in the `Setting` row. The result is
 * multiplied by the term length straight into `chargeCents` and `renewalCharge`,
 * and from there into debitWallet, Stripe's `unit_amount` and an Invoice row —
 * all of which are integer cents. `extraDiskPerGbCents` has always clamped; this
 * one did not.
 * ------------------------------------------------------------------ */

test("a fractional add-on price would produce a charge that is not whole cents", () => {
  // Why the clamp is a money guard and not tidiness: this is what a "2.5" setting
  // does to a real renewal before anything rejects it.
  const dirty = renewalCharge(
    {
      termMonths: 12,
      extraDiskGB: 0,
      plan: { name: "Starter", priceCents: 899 },
      gamePlan: null,
      dedicatedIp: {},
    },
    { ipMonthlyCents: 2.5, extraDiskPerGbCents: 0 },
  );
  assert.ok(!Number.isInteger(dirty.totalCents), "2.5c/mo x 12 lands mid-cent");
  // Clamped at the source, the same renewal is payable.
  const clean = renewalCharge(
    {
      termMonths: 12,
      extraDiskGB: 0,
      plan: { name: "Starter", priceCents: 899 },
      gamePlan: null,
      dedicatedIp: {},
    },
    { ipMonthlyCents: Math.max(0, Math.round(2.5)), extraDiskPerGbCents: 0 },
  );
  assert.equal(clean.totalCents, vpsTermPriceCents(899, 12) + 3 * 12);
  assert.ok(Number.isInteger(clean.totalCents));
});

test("a negative add-on price can never discount the plan", () => {
  const discounted = renewalCharge(
    {
      termMonths: 1,
      extraDiskGB: 0,
      plan: { name: "Starter", priceCents: 899 },
      gamePlan: null,
      dedicatedIp: {},
    },
    { ipMonthlyCents: -500, extraDiskPerGbCents: 0 },
  );
  assert.equal(discounted.totalCents, 399, "unclamped, a -$5 setting sells a $8.99 plan for $3.99");
  assert.equal(Math.max(0, Math.round(-500)), 0, "clamped, it is simply free");
});

test("both admin-priced add-ons normalise their setting the same way", () => {
  assert.match(
    DEDICATED_IP,
    /const v = await getSettingInt\("dedicated_ip_price_cents", DEDICATED_IP_PRICE_CENTS\);\s*return Math\.max\(0, Math\.round\(v\)\);/,
    "the dedicated-IP surcharge is clamped to whole non-negative cents",
  );
  const disk = code("../lib/disk-expand.ts");
  assert.match(disk, /return Math\.max\(0, Math\.round\(v\)\);/, "and the extra-disk price still is too");
});

