import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
  MS_PER_AVG_MONTH,
  prorateBlendPercent,
  prorateDeltaCents,
  prorateUpgradeCents,
  prorateDowngradeCreditCents,
  remainingMonths,
  resolveTermPromoPercent,
} from "../lib/proration.ts";
import { vpsTermPriceCents, vpsEffectiveMonthly } from "../lib/billing-terms.ts";
import {
  currentPromo,
  deepestPromoPercent,
  promoPriceCents,
  SEASONAL_PROMOS,
  LAUNCH_SALE,
  type Promo,
} from "../lib/promotions.ts";

/**
 * REAL INCIDENTS — docs/QA-PRELAUNCH.md P0-6 (and its mirror images):
 *
 *  1. Upgrade proration priced the RAW list-price monthly delta while the original
 *     order applied both the term discount and the seasonal promo. On a 36-month
 *     term with the 30% Summer Sale running, upgrading Starter -> Max the day after
 *     purchase cost $1,044.45 against $665.08 for buying Max outright on the same
 *     end date: the customer overpaid $379.37.
 *  2. The downgrade CREDIT used that same undiscounted delta, so it refunded more
 *     than had ever been paid — a self-service money printer that was one
 *     cheap-but-storage-heavy plan away from reachable (blocked today only by the
 *     disk-monotonic guard, QA P1-14).
 *  3. The fix for (2) also CAPPED the credit's duration at one term while the
 *     charge side kept pricing every remaining month, which broke the round trip in
 *     the other direction. A customer whose stacked "Renew now" had pushed
 *     `expiresAt` 36 months out on a 12-month term paid $544.32 to go
 *     Starter -> Max and got $181.44 back coming straight down: the platform kept
=== tail ===
});

/**
 * TRIPWIRE on the write sites. The persisted rate is only as good as the code that
 * writes it: a term sold or extended without recording its rate leaves a NULL, and
 * NULL is priced at the conservative floor rather than at what was actually paid.
 */
test("every path that sells, renews or gifts a term records the rate it was sold at", () => {
  const sites: [string, string, string][] = [
    // `promoPercent`, not `promo.discountPercent`: a card-paid order settles the
    // price stamped on its Checkout session BEFORE the card was charged (see
    // OrderPrice in lib/order.ts), so the rate that produced that price is the rate
    // the term was sold at — and it may no longer be the promo running at confirm.
    // Recording today's rate against money collected under a different one is the
    // exact drift this column exists to prevent.
    ["lib/order.ts", "termPromoPercent: freeRequested ? 100 : promoPercent", "initial order (shared core)"],
    ["lib/actions.ts", "termPromoPercent: freeRequested ? 100 : promo.discountPercent", "initial order (form action)"],
    ["lib/actions-gameplans.ts", "termPromoPercent: 0", "game plan — flat price, no promo"],
    ["lib/actions.ts", "termPromoPercent: renewedPercent", "renewNow"],
    ["worker/billing.ts", "termPromoPercent: renewedPercent", "auto-renew sweep"],
    ["lib/actions.ts", "termPromoPercent: 100", "admin free grant / set-free"],
  ];
  for (const [file, needle, what] of sites) {
    assert.ok(readNormalized(file).includes(needle), `${file} must record the sold rate for: ${what}`);
  }
  // Both renewal paths must BLEND rather than overwrite, or renewing early
  // silently reprices months still running at an intro discount.
  for (const file of ["lib/actions.ts", "worker/billing.ts"]) {
    assert.ok(
      readNormalized(file).includes("prorateBlendPercent({ currentPercent: resolveTermPromoPercent("),
      `${file} must blend the renewal into the existing rate, not overwrite it`,
    );
  }
  // adminExtendServer moves expiresAt with no payment; the gifted months must be
  // recorded at 100% off or proration pays out months nobody bought.
  assert.ok(
    readNormalized("lib/actions.ts").includes("addedPercent: 100, // gifted: no cash changed hands for these months"),
    "adminExtendServer must record gifted months as sold at 100% off",
  );
});

