cd /opt/nxeon && cat >> test/billing-terms.test.ts <<'EOF'

/**
 * REAL DEFECT (2026-07-27 money-core audit): `vpsEffectiveMonthly` divided by
 * `months` with no guard, so `months <= 0` produced `0 / 0` = NaN. That is not a
 * display problem. `prorateDeltaCents` (lib/proration.ts) prices BOTH halves of
 * every upgrade charge and downgrade credit through this function using
 * `Server.termMonths`, and NaN does not stop at the clamp: `Math.max(0, NaN)` is
 * NaN, because NaN is not greater than 0. The NaN travels on as the amount to
 * debit — past `if (cents <= 0) return` in debitWallet, which NaN also fails — and
 * lands in a Prisma `decrement`. The column defaults to 1 and every writer clamps
 * to >= 1 today, so this is a latch rather than a live bug; a shared money function
 * still must not be able to emit a NaN.
 */
test("a zero or negative term never produces NaN money", () => {
  assert.equal(vpsEffectiveMonthly(899, 0), 899, "no term discount to spread — the monthly price stands");
  assert.equal(vpsEffectiveMonthly(899, -12), 899);
  assert.equal(vpsEffectiveMonthly(899, Number.NaN), 899);
  for (const months of [0, -12, Number.NaN]) {
    assert.ok(Number.isFinite(vpsEffectiveMonthly(899, months)), `months=${months} must stay finite`);
  }
  // The clamp that everyone assumes protects them does NOT stop a NaN.
  assert.ok(Number.isNaN(Math.max(0, Number.NaN)), "which is exactly why the guard has to be here");
});
EOF
npx tsx --test test/billing-terms.test.ts 2>&1 | grep -E "^not ok|^# (tests|pass|fail)"

cd /opt/nxeon && cat >> test/proration.test.ts <<'EOF'

/**
 * REAL DEFECT (2026-07-27 money-core audit), the consequence of the
 * `vpsEffectiveMonthly` division guard added in test/billing-terms.test.ts, pinned
 * HERE because this is the file where the number becomes a charge.
 *
 * `prorateUpgradeCents` and `prorateDowngradeCreditCents` both end in
 * `Math.max(0, ±delta)`, and every reader of that line assumes it makes the result
 * safe. It does not: `Math.max(0, NaN)` is NaN. A NaN rate basis therefore reached
 * `debitWallet(tx, userId, NaN)` — where `if (cents <= 0) return` is also false for
 * NaN — and became a Prisma `decrement: NaN` against a customer's balance.
 */
test("no combination of inputs lets a proration emit NaN or Infinity", () => {
  const hostile: { termMonths: number; monthsRemaining: number; termPromoPercent: number | null }[] = [
    { termMonths: 0, monthsRemaining: 12, termPromoPercent: 0 },
    { termMonths: -12, monthsRemaining: 12, termPromoPercent: 0 },
    { termMonths: Number.NaN, monthsRemaining: 12, termPromoPercent: null },
    { termMonths: 12, monthsRemaining: 0, termPromoPercent: 45 },
    { termMonths: 12, monthsRemaining: -5, termPromoPercent: 100 },
  ];
  for (const h of hostile) {
    const opts = { fromMonthlyCents: 899, toMonthlyCents: 3299, ...h };
    for (const [name, value] of [
      ["delta", prorateDeltaCents(opts)],
      ["upgrade", prorateUpgradeCents(opts)],
      ["credit", prorateDowngradeCreditCents({ ...opts, fromMonthlyCents: 3299, toMonthlyCents: 899 })],
    ] as const) {
      assert.ok(Number.isFinite(value), `${name} was ${value} for ${JSON.stringify(h)}`);
      assert.ok(Number.isInteger(value), `${name} must be whole cents, got ${value}`);
    }
    assert.ok(prorateUpgradeCents(opts) >= 0, "an upgrade never pays the customer");
  }
});

test("a zero-month term still prices a round trip to exactly zero", () => {
  // The guard must not break the invariant this whole file exists for: whatever the
  // basis resolves to, up and back down must cancel.
  const opts = { termMonths: 0, monthsRemaining: 12, termPromoPercent: 0 };
  const up = prorateUpgradeCents({ ...opts, fromMonthlyCents: 899, toMonthlyCents: 3299 });
  const down = prorateDowngradeCreditCents({ ...opts, fromMonthlyCents: 3299, toMonthlyCents: 899 });
  assert.equal(up, down, "the round trip nets to zero even on a degenerate term");
});
EOF
npx tsx --test test/proration.test.ts 2>&1 | grep -E "^not ok|^# (tests|pass|fail)"

cd /opt/nxeon && cat >> test/pricing-display-vs-charge.test.ts <<'EOF'

/* ------------------------------------------------------------------ *
 * The extra-disk proration was derived TWICE (2026-07-27 money-core audit)
 *
 * `diskExpandQuote` (lib/disk-expand.ts) computed the one-off charge inline:
 *
 *     const remainingMonths = Math.max(0, (expiresAt.getTime() - Date.now()) / MS_PER_AVG_MONTH);
 *     prorateCents = Math.max(0, Math.round(monthlyCents * remainingMonths));
 *
 * …over a `MS_PER_AVG_MONTH` re-exported from lib/resize.ts, which declared its own
 * `30.44 * 86400_000` alongside the one in lib/proration.ts. Meanwhile
 * components/customer/AddStorage.tsx — the control that SHOWS the customer this
 * figure and takes their consent for it — held a THIRD private copy of the constant
 * and a fourth copy of the expression.
 *
 * Nothing was wrong with any of the four. That is precisely the pattern this
 * codebase keeps getting hurt by: the wizard's promo line, the "+30 days" renew
 * button, the resize picker before it moved onto lib/proration.ts. Three constants
 * that happen to be equal are still three constants, and the day one is tuned the
 * quote and the charge diverge with nothing to catch it.
 *
 * There is now ONE constant (lib/proration.ts) and ONE prorating function
 * (`extraDiskProrateCents`, in the pure client-importable lib/extra-disk.ts, next
 * to `extraDiskCentsAt` for the same reason `walletSplit` is where it is).
 * ------------------------------------------------------------------ */

test("the extra-disk proration has exactly one constant and one formula", async () => {
  const { MS_PER_AVG_MONTH } = await import("../lib/proration.ts");
  const resize = await import("../lib/resize.ts");
  assert.equal(resize.MS_PER_AVG_MONTH, MS_PER_AVG_MONTH, "lib/resize.ts re-exports it, never redeclares");
  const resizeSrc = readFileSync(join(REPO, "lib/resize.ts"), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
  assert.ok(
    !/export const MS_PER_AVG_MONTH/.test(resizeSrc),
    "a second declaration of the month length is a second money constant",
  );
  const expandSrc = readFileSync(join(REPO, "lib/disk-expand.ts"), "utf8")
    .replace(/\/\*[\s\S]*?\*\//g, "")
    .replace(/^\s*\/\/.*$/gm, "");
  assert.match(
    expandSrc,
    /extraDiskProrateCents\(monthlyCents, remainingMonths\(server\.expiresAt, Date\.now\(\)\)\)/,
    "the server charge goes through the shared pair",
  );
  assert.ok(!/MS_PER_AVG_MONTH/.test(expandSrc), "and derives no month arithmetic of its own");
});

/**
 * AddStorage.tsx is a client component and cannot be imported here (it pulls the
 * whole React runtime in), so its formula is reproduced — exactly as
 * `wizardPromoCents` above reproduces the deploy wizard's. The tripwire below fails
 * if the real line stops matching this copy, which is what forces a re-check.
 */
const addStorageProrate = (monthlyCents: number, expiresAtMs: number, nowMs: number) =>
  Math.max(0, Math.round(monthlyCents * Math.max(0, (expiresAtMs - nowMs) / (30.44 * 86400_000))));

test("what Add storage shows is what diskExpandQuote charges, over every term", async () => {
  const { extraDiskProrateCents } = await import("../lib/extra-disk.ts");
  const { remainingMonths } = await import("../lib/proration.ts");
  const now = Date.parse("2026-07-27T00:00:00.000Z");
  // Real purchasable amounts at the live $0.10/GB/mo, across every VPS term plus a
  // stacked "Renew now" window and a term with hours left on it.
  for (const gb of [10, 50, 100, 250, 500]) {
    for (const months of [0.002, 1, 12, 24, 36, 72]) {
      const monthlyCents = extraDiskCentsAt(gb, 10);
      const expiresAt = now + months * 30.44 * 86400_000;
      const charged = extraDiskProrateCents(monthlyCents, remainingMonths(new Date(expiresAt), now));
      const shown = addStorageProrate(monthlyCents, expiresAt, now);
      assert.equal(shown, charged, `${gb} GB over ${months} months: shown ${shown} != charged ${charged}`);
    }
  }
  // An expired term prorates to nothing rather than crediting the customer.
  assert.equal(extraDiskProrateCents(500, remainingMonths(new Date(now - 86400_000), now)), 0);
  // 50 GB at 10c/GB/mo for a full year is the figure a customer actually sees.
  assert.equal(extraDiskProrateCents(extraDiskCentsAt(50, 10), 12), 6000);
});

test("the Add storage control still computes the figure this test reproduces", () => {
  const src = readNormalized("components/customer/AddStorage.tsx");
  assert.ok(
    src.includes("Math.max(0, (new Date(expiresAt).getTime() - Date.now()) / MS_PER_AVG_MONTH)"),
    "AddStorage's remaining-term expression changed — re-check it against remainingMonths in " +
      "lib/proration.ts and update addStorageProrate above",
  );
  assert.ok(
    src.includes("const monthlyCents = extraDiskCentsAt(addGB, pricePerGbCents)"),
    "the monthly figure must keep coming from the shared lib/extra-disk.ts helper",
  );
  // The permanent fix is for AddStorage to import extraDiskProrateCents +
  // remainingMonths, exactly as ResizePicker imports prorateUpgradeCents. Until it
  // does, this pair of assertions is what keeps the copy honest.
});
EOF
